<?php

namespace App\Policies;

use App\Models\CashFlow;
use App\Models\User;

class CashFlowPolicy
{
    public function viewAny(User $user): bool
    {
        return $user->is_active && $user->isOwner();
    }

    public function view(User $user, CashFlow $cashFlow): bool
    {
        return $user->is_active && $user->isOwner();
    }

    public function create(User $user): bool
    {
        return $user->is_active && $user->isOwner();
    }

    /**
     * Auto-generated income rows from OrderPayment are immutable for audit integrity.
     */
    public function update(User $user, CashFlow $cashFlow): bool
    {
        return $user->is_active && $user->isOwner() && ! $cashFlow->isAutoGenerated();
    }

    public function delete(User $user, CashFlow $cashFlow): bool
    {
        return $user->is_active && $user->isOwner() && ! $cashFlow->isAutoGenerated();
    }

    public function deleteAny(User $user): bool
    {
        return false;
    }
}
